// Generated by build_motion_assets.py. Read-only sparse photo sprites.
// Inputs are sampled into THREE register stages. out_valid/out_x/out_y/out_rgb
// refer to the same input pixel. Delay raster hsync/vsync/DE by three clocks if
// they bypass this module. RGB palette decoding after stage 2 is combinational.
// Scene 0/1/3 are exact pass-through (except latency). Scene 2 is erhu, 4 tanggu.
// Source/background coordinates are fixed 1024x600. Drum offset is an upward
// lift in pixels; zero is the impact position. Bow tilt uses integer shears
// around its photographed string contact, not an extra rotated sprite ROM.
`include "heritage_geometry.vh"
module heritage_motion_layer #(
`ifdef __ICARUS__
    parameter SPAN_FILE="rtl/heritage_motion_spans.hex",
    parameter PIXEL_FILE="rtl/heritage_motion_pixels.hex"
`else
    parameter SPAN_FILE="heritage_motion_spans.hex",
    parameter PIXEL_FILE="heritage_motion_pixels.hex"
`endif
)(
    input clk,input rst,input [2:0] scene,
    input signed [5:0] bow_offset,input signed [5:0] bow_angle,
    input [4:0] drum_offset,input [4:0] drum_right_offset,
    input valid,input [10:0] x,input [10:0] y,input [23:0] rgb,
    output out_valid,output [10:0] out_x,output [10:0] out_y,
    output [23:0] out_rgb
);
    // Two independent synchronous reads infer one true-dual-port metadata ROM.
    reg [23:0] span_rom [0:1251];
    reg [3:0] pixel_rom [0:19181];
    initial begin
        $readmemh(SPAN_FILE,span_rom);
        $readmemh(PIXEL_FILE,pixel_rom);
    end
    reg [10:0] span_address;
    reg signed [11:0] source_x;
    reg signed [11:0] pivot_dx,y_lift;
    reg signed [6:0] angle;
    reg selected;
    always @* begin
        source_x=$signed({1'b0,x});
        pivot_dx=0;y_lift=0;angle=0;
        selected=1'b0;
        span_address=0;
        if(scene==3'd2) begin
            source_x=$signed({1'b0,x})-$signed({{6{bow_offset[5]}},bow_offset});
            pivot_dx=source_x-$signed({1'b0,`ERHU_CONTACT_X});
            angle=-$signed({bow_angle[5],bow_angle});
            if(source_x>=133 && source_x<=920) begin
                selected=1'b1;
                span_address=source_x-133;
            end
        end else if(scene==3'd4) begin
            if(x>=154 && x<=387) begin
                selected=1'b1;
                span_address=11'd788+x-154;
                pivot_dx=$signed({1'b0,x})-$signed({1'b0,`DRUM_LEFT_X});
                angle=$signed({1'b0,drum_offset,1'b0});
                y_lift=$signed({7'd0,drum_offset});
            end else if(x>=647 && x<=875) begin
                selected=1'b1;
                span_address=11'd1022+x-647;
                pivot_dx=$signed({1'b0,x})-$signed({1'b0,`DRUM_RIGHT_X});
                angle=-$signed({1'b0,drum_right_offset,1'b0});
                y_lift=$signed({7'd0,drum_right_offset});
            end
        end
    end
    // One shared signed multiplier replaces discontinuous angle thresholds.
    // Geometry is registered before ROM access to keep the pixel path short.
    reg [10:0] span_address_g,x_g,y_g;
    reg selected_g,valid_g;
    reg [23:0] rgb_g;
    reg signed [11:0] pivot_g,lift_g;
    reg signed [6:0] angle_g;
    reg signed [18:0] shear_d;
    reg signed [11:0] y_base_d;
    reg [23:0] span0_d,span1_d;
    reg selected_d,valid_d,valid_dd,hit_dd;
    reg [10:0] x_d,y_d,x_dd,y_dd;
    reg [23:0] rgb_d,rgb_dd;
    reg [3:0] texel_dd;
    wire [14:0] first_offset=span0_d[14:0];
    wire [14:0] next_offset=span1_d[14:0];
    wire [8:0] first_y=span0_d[23:15];
    wire [14:0] span_height=next_offset-first_offset;
    wire signed [12:0] source_y_d=$signed(y_base_d)+(shear_d>>>10);
    wire [11:0] relative_y=source_y_d-$signed({4'd0,first_y});
    wire hit=selected_d && source_y_d>=$signed({4'd0,first_y})
             && {3'd0,relative_y}<span_height;
    wire [14:0] pixel_address=hit ? first_offset+{3'd0,relative_y} : 15'd0;
    // Do not reset ROM-read registers: this permits block-RAM inference.
    always @(posedge clk) begin
        span0_d<=span_rom[span_address_g];
        span1_d<=span_rom[span_address_g+11'd1];
        shear_d<=pivot_g*angle_g;
        texel_dd<=pixel_rom[pixel_address];
    end
    always @(posedge clk or posedge rst) begin
        if(rst) begin
            selected_d<=0; valid_d<=0; valid_dd<=0; hit_dd<=0;
            span_address_g<=0;selected_g<=0;valid_g<=0;x_g<=0;y_g<=0;
            pivot_g<=0;angle_g<=0;lift_g<=0;rgb_g<=0;y_base_d<=0;
            x_d<=0; y_d<=0; x_dd<=0; y_dd<=0;
            rgb_d<=0; rgb_dd<=0;
        end else begin
            span_address_g<=span_address;selected_g<=selected;
            valid_g<=valid;x_g<=x;y_g<=y;rgb_g<=rgb;
            pivot_g<=pivot_dx;angle_g<=angle;lift_g<=y_lift;
            selected_d<=selected_g;y_base_d<=$signed({1'b0,y_g})+lift_g;
            valid_d<=valid_g; x_d<=x_g; y_d<=y_g; rgb_d<=rgb_g;
            valid_dd<=valid_d; x_dd<=x_d; y_dd<=y_d; rgb_dd<=rgb_d;
            hit_dd<=hit;
        end
    end
    function [23:0] palette_rgb;
        input [3:0] index;
        begin
            case(index)
            4'd1: palette_rgb=24'hf5dfc0;
            4'd2: palette_rgb=24'he3ba91;
            4'd3: palette_rgb=24'hdea778;
            4'd4: palette_rgb=24'hcba17e;
            4'd5: palette_rgb=24'hc99269;
            4'd6: palette_rgb=24'hc77c44;
            4'd7: palette_rgb=24'ha78167;
            4'd8: palette_rgb=24'ha06f4e;
            4'd9: palette_rgb=24'ha66232;
            4'd10: palette_rgb=24'h9f531f;
            4'd11: palette_rgb=24'h8b532e;
            4'd12: palette_rgb=24'h785033;
            4'd13: palette_rgb=24'h7d4016;
            4'd14: palette_rgb=24'h713208;
            4'd15: palette_rgb=24'h4d270f;
            default: palette_rgb=24'h000000;
            endcase
        end
    endfunction
    assign out_valid=valid_dd;
    assign out_x=x_dd;
    assign out_y=y_dd;
    assign out_rgb=(hit_dd && texel_dd!=4'd0) ? palette_rgb(texel_dd) : rgb_dd;
endmodule
